add_action( 'woocommerce_product_meta_end', 'perfectpixel_show_shipping_class' );

function perfectpixel_show_shipping_class() {
	global $product;
	if ( ! $product || ! $product->get_shipping_class_id() ) {
		return;
	}
	$term = get_term( $product->get_shipping_class_id(), 'product_shipping_class' );
	if ( $term && ! is_wp_error( $term ) ) {
		echo '<span class="shipping_class_wrapper">' . esc_html( '{{shipping_class_label}}' ) . ' <span class="shipping_class">' . esc_html( $term->name ) . '</span></span>';
	}
}
